AIAdmin = {
    init: async function (app, container) {
        container = container || $('.component[name=AIAdmin]');
        try {
            var response = await fetch('/Api/AI/Model/Providers', { credentials: 'same-origin' });
            if (!response.ok) throw new Error('HTTP ' + response.status);
            var result = await response.json();
            var providers = result.value || result.providers || result;
            if (!Array.isArray(providers)) providers = [];
            var list = $('[data-ai-providers]', container).empty();
            providers.forEach(function (provider) { $('<li>').text(provider.name || provider.Name || provider.key || provider.Key || String(provider)).appendTo(list); });
            if (!providers.length) list.append('<li>No provider inventory was returned; use model discovery to verify a known key.</li>');
        } catch (_) {
            $('[data-ai-providers]', container).html('<li>Provider inventory is not exposed by this deployment.</li>');
        }
    }
}
